/// The handwriting font for the Principal's signature on printed ID cards: Great Vibes
/// (SIL Open Font License 1.1, (c) 2015 The Great Vibes Pro Project Authors), plain English letters only.
/// Kept inside the app as text because pictures and font files cannot be copy-pasted.
pw.Font? _sign;
pw.Font signatureFont() {
  try { return _sign ??= pw.Font.ttf(ByteData.sublistView(base64Decode(_greatVibes))); } catch (_) { return pw.Font.timesBoldItalic(); }
}

